class Solution {
  public String getSmallestString(String s, int k) {
    char[] c = s.toCharArray();
    for (int i = 0; i < c.length && k > 0; i++) {
      int toA = Math.min(c[i] - 'a', 26 - (c[i] - 'a'));
      if (toA <= k) {
        k -= toA;
        c[i] = 'a';
      } else {
        c[i] -= k; // not enough budget to reach 'a': step down as far as possible
        k = 0;
      }
    }
    return new String(c);
  }
}
